Example
Join the matching "products" document(s) to the "orders" collection:

  var MongoClient = require('mongodb').MongoClient;var url = "mongodb://127.0.0.1:27017/";
MongoClient.connect(url, function(err, db) {  if (err) throw err;  
  var dbo = db.db("mydb");  
  dbo.collection('orders').aggregate([    { $lookup:       
  {         from: 'products',         
  localField: 'product_id',         
  foreignField: '_id',         
  as: 'orderdetails'       }     
  }    ]).toArray(function(err, 
  res) {    if (err) throw err;    
  console.log(JSON.stringify(res));    
  db.close();  });});
